observation.command:
su postgres -c "createdb --owner root consul_production" && su postgres -c "psql -d consul_production" <<'SQL'
CREATE SCHEMA IF NOT EXISTS shared_extensions AUTHORIZATION root;
CREATE EXTENSION IF NOT EXISTS plpgsql;
CREATE EXTENSION IF NOT EXISTS unaccent  SCHEMA shared_extensions;
CREATE EXTENSION IF NOT EXISTS pg_trgm   SCHEMA shared_extensions;
SQL
echo "DB created: $?"; psql -h localhost -U root -d consul_production -t -c "select extname, nspname from pg_extension join pg_namespace on pg_namespace.oid=pg_extnamespaceid;"
